/** @param {NS} ns */
export async function main(ns) {
  const home = ns.getServer('home');
  const money = home.moneyAvailable || 0;

  // Scan for nearby servers
  const scan = ns.scan('home');
  ns.print(`Connected servers: ${scan.length}`);

  // Find n00dles if available
  if (scan.includes('n00dles')) {
    const target = ns.getServerMoneyAvailable('n00dles');
    const maxMoney = ns.getServerMaxMoney('n00dles');
    const security = ns.getServerSecurityLevel('n00dles');

    ns.print(`n00dles - Money: ${ns.formatNumber(target)} / ${ns.formatNumber(maxMoney)}`);
    ns.print(`Security: ${ns.formatNumber(security)}`);

    // Recommendation
    if (money > 50000) {
      ns.print('RECOMMENDATION: Buy first program (BruteSSH.exe)');
    } else {
      ns.print(`RECOMMENDATION: Save money. Need $50k, have ${ns.formatNumber(money)}`);
    }
  }

  ns.print(`Current money: ${ns.formatNumber(money)}`);
}

